function applyFilmData(data){for(const m of data.movies){const film=FILMS[m.id];if(film&&['Beyond the Horizon','Midnight in Kyoto','The Last Orbit','Little Forest Club','After the Rain','Echoes'].includes(m.name))Object.assign(m,film);}if(data.rooms.some(r=>!r.movie)){for(const r of data.rooms)if(!r.movie)r.movie={r1:'m1',r2:'m2',r3:'m3'}[r.id]||'m1';for(const r of seed().rooms)if(!data.rooms.some(x=>x.id===r.id))data.rooms.push(r);}if(!data.movies.some(m=>m.id==='m7'))data.movies.push({id:'m7',active:true,upcoming:false,...FILMS.m7});for(const c of data.cinemas)if(!data.rooms.some(r=>r.id===c.id+'-m7'))data.rooms.push({id:c.id+'-m7',cinema:c.id,movie:'m7',name:'Theater 05',type:'2D',active:true});for(const [id,film] of Object.entries(FILMS)){if(!data.movies.some(m=>m.id===id))data.movies.push({id,active:true,upcoming:false,...film});if(Number(id.slice(1))>=8)for(const c of data.cinemas)if(!data.rooms.some(r=>r.id===c.id+'-'+id))data.rooms.push({id:c.id+'-'+id,cinema:c.id,movie:id,name:'Theater '+id.slice(1).padStart(2,'0'),type:film.type||'2D',active:true});}data.catalogueVersion=2;return data;}
